namespace {
enum struct ChannelMode : std::uint8_t { Y, UV, YUV, RGB };

struct NLMData {
    VSNode* node = nullptr; // clip
    const VSVideoInfo* vi = nullptr;
    int d = 0;
    int a = 0;
    int s = 0;
    float h = 0.0f;
    float h2_inv_norm = 0.0f;
    ChannelMode channels = ChannelMode::Y;
    decltype(&ispc::nlmVerticalWelsch) nlm_vertical = nullptr; // wmode
    float wref = 0.0f;
    VSNode* ref_node = nullptr; // rclip

    // run-time resources
    std::shared_mutex workspaces_lock;
    std::unordered_map<std::thread::id, float*> workspaces;
};
} // namespace

template <typename T> [[nodiscard]] static inline auto castVoidPtr(T* p) noexcept {
    if constexpr (std::is_const_v<T>) {
        return reinterpret_cast<const void*>(p);
    } else {
        return reinterpret_cast<void*>(p);
    }
}

template <typename T1, typename T2>
[[nodiscard]] static inline std::array<T1*, 3> castPtrs(std::array<T2*, 3> ptrs) noexcept {
    return {
        reinterpret_cast<T1*>(ptrs[0]),
        reinterpret_cast<T1*>(ptrs[1]),
        reinterpret_cast<T1*>(ptrs[2]),
    };
}

template <typename T> static inline constexpr T square(T x) noexcept {
    return x * x;
}

// T: (const) VSFrameRef
template <typename T> static inline auto getPtrs(T* frame, ChannelMode channels, const VSAPI* vsapi) noexcept {

    using value_type = std::conditional_t<std::is_const_v<T>, const void, void>;

    std::array<value_type*, 3> ptrs{};

    auto get_ptr = [frame, vsapi](int plane) {
        if constexpr (std::is_const_v<T>) {
            return castVoidPtr(vsapi->getReadPtr(frame, plane));
        } else {
            return castVoidPtr(vsapi->getWritePtr(frame, plane));
        }
    };

    switch (channels) {
    case ChannelMode::Y:
        ptrs[0] = get_ptr(0);
        break;
    case ChannelMode::UV:
        ptrs[1] = get_ptr(1);
        ptrs[2] = get_ptr(2);
        break;
    case ChannelMode::YUV:
    case ChannelMode::RGB:
        ptrs[0] = get_ptr(0);
        ptrs[1] = get_ptr(1);
        ptrs[2] = get_ptr(2);
        break;
    }

    return ptrs;
}

static inline void nlmDistanceDispatch_f32(
    float* temp0,
    std::array<const float*, 3> centerp,
    std::array<const float*, 3> neighborp,
    int offset_x,
    int offset_y,
    int width,
    int height,
    int stride,
    ChannelMode channels
) noexcept {

    switch (channels) {
    case ChannelMode::Y:
        ispc::nlmDistanceLuma_f32(temp0, centerp[0], neighborp[0], offset_x, offset_y, width, height, stride);
        break;
    case ChannelMode::UV:
        ispc::nlmDistanceChroma_f32(
            temp0, centerp[1], centerp[2], neighborp[1], neighborp[2], offset_x, offset_y, width, height, stride
        );
        break;
    case ChannelMode::YUV:
        ispc::nlmDistanceYUV_f32(
            temp0,
            centerp[0],
            centerp[1],
            centerp[2],
            neighborp[0],
            neighborp[1],
            neighborp[2],
            offset_x,
            offset_y,
            width,
            height,
            stride
        );
        break;
    case ChannelMode::RGB:
        ispc::nlmDistanceRGB_f32(
            temp0,
            centerp[0],
            centerp[1],
            centerp[2],
            neighborp[0],
            neighborp[1],
            neighborp[2],
            offset_x,
            offset_y,
            width,
            height,
            stride
        );
        break;
    }
}

