static inline void nlmDistance(
    float* temp0,
    std::array<const void*, 3> centerp,
    std::array<const void*, 3> neighborp,
    int offset_x,
    int offset_y,
    int width,
    int height,
    int stride,
    ChannelMode channels,
    int bits
) noexcept {

    if (bits == 32) {
        nlmDistanceDispatch_f32(
            temp0,
            castPtrs<const float>(centerp),
            castPtrs<const float>(neighborp),
            offset_x,
            offset_y,
            width,
            height,
            stride,
            channels
        );
    } else if (bits <= 8) {
        float inv_divisor = 1.0f / static_cast<float>((1 << bits) - 1);
        nlmDistanceDispatch_u8(
            temp0,
            castPtrs<const uint8_t>(centerp),
            castPtrs<const uint8_t>(neighborp),
            offset_x,
            offset_y,
            width,
            height,
            stride,
            channels,
            inv_divisor
        );
    } else if (bits <= 16) {
        float inv_divisor = 1.0f / static_cast<float>((1 << bits) - 1);
        nlmDistanceDispatch_u16(
            temp0,
            castPtrs<const uint16_t>(centerp),
            castPtrs<const uint16_t>(neighborp),
            offset_x,
            offset_y,
            width,
            height,
            stride,
            channels,
            inv_divisor
        );
    } else {
        assert(false);
    }
}

static inline void nlmAccumulationDispatch_f32(
    float* weightp,
    std::array<float*, 3> wdstp,
    float* max_weightp,
    std::array<const float*, 3> srcp_bwd,
    std::array<const float*, 3> srcp_fwd,
    const float* temp_bwd,
    const float* temp_fwd,
    int offset_x,
    int offset_y,
    int width,
    int height,
    int stride,
    ChannelMode channels
) noexcept {

    switch (channels) {
    case ChannelMode::Y:
        ispc::nlmAccumulationCh1_f32(
            weightp,
            wdstp[0],
            max_weightp,
            srcp_bwd[0],
            srcp_fwd[0],
            temp_bwd,
            temp_fwd,
            offset_x,
            offset_y,
            width,
            height,
            stride
        );
        break;
    case ChannelMode::UV:
        ispc::nlmAccumulationCh2_f32(
            weightp,
            wdstp[0],
            wdstp[1],
            max_weightp,
            srcp_bwd[1],
            srcp_bwd[2],
            srcp_fwd[1],
            srcp_fwd[2],
            temp_bwd,
            temp_fwd,
            offset_x,
            offset_y,
            width,
            height,
            stride
        );
        break;
    case ChannelMode::YUV:
    case ChannelMode::RGB:
        ispc::nlmAccumulationCh3_f32(
            weightp,
            wdstp[0],
            wdstp[1],
            wdstp[2],
            max_weightp,
            srcp_bwd[0],
            srcp_bwd[1],
            srcp_bwd[2],
            srcp_fwd[0],
            srcp_fwd[1],
            srcp_fwd[2],
            temp_bwd,
            temp_fwd,
            offset_x,
            offset_y,
            width,
            height,
            stride
        );
        break;
    }
}

