static inline void nlmFinishDispatch_f32(
    std::array<float*, 3> dstp,
    std::array<const float*, 3> srcp,
    const float* weightp,
    std::array<float*, 3> wdstp,
    const float* max_weightp,
    float wref,
    int width,
    int height,
    int stride,
    ChannelMode channels
) noexcept {

    switch (channels) {
    case ChannelMode::Y:
        ispc::nlmFinishCh1_f32(dstp[0], srcp[0], weightp, wdstp[0], max_weightp, wref, width, height, stride);
        break;
    case ChannelMode::UV:
        ispc::nlmFinishCh2_f32(
            dstp[1], dstp[2], srcp[1], srcp[2], weightp, wdstp[0], wdstp[1], max_weightp, wref, width, height, stride
        );
        break;
    case ChannelMode::YUV:
    case ChannelMode::RGB:
        ispc::nlmFinishCh3_f32(
            dstp[0],
            dstp[1],
            dstp[2],
            srcp[0],
            srcp[1],
            srcp[2],
            weightp,
            wdstp[0],
            wdstp[1],
            wdstp[2],
            max_weightp,
            wref,
            width,
            height,
            stride
        );
        break;
    }
}

